begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) values('af400000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','f4-owner@example.test',now(),now(),now());
insert into public.organizations(id,name,slug,status) values('bf400000-0000-4000-8000-000000000001','F4 fictício','f4-synthetic','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values('cf400000-0000-4000-8000-000000000001','bf400000-0000-4000-8000-000000000001','Sede F4','sede','headquarters');
insert into public.organization_memberships(organization_id,user_id,role,status,default_unit_id) values('bf400000-0000-4000-8000-000000000001','af400000-0000-4000-8000-000000000001','owner','active','cf400000-0000-4000-8000-000000000001');
select set_config('f4.org','bf400000-0000-4000-8000-000000000001',true);select set_config('f4.unit','cf400000-0000-4000-8000-000000000001',true);
select ok(not has_function_privilege('authenticated','public.finance_digital_ingest(uuid,jsonb)','execute'),'cliente não pode fabricar prova de pagamento');
select ok(not has_function_privilege('anon','public.finance_digital(uuid,uuid,text,jsonb)','execute'),'visitante sem acesso financeiro');
select ok(not has_table_privilege('authenticated','private.finance_digital_receipts','update'),'cliente sem alteração direta');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"af400000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.finance_digital(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'list','{}')$$,'listagem vazia autorizada funciona');
select public.finance_f1(current_setting('f4.org')::uuid,array[current_setting('f4.unit')::uuid],'catalog','{"id":"df400000-0000-4000-8000-000000000001","kind":"account","name":"Banco F4"}');
select public.finance_f1(current_setting('f4.org')::uuid,array[current_setting('f4.unit')::uuid],'catalog','{"id":"df400000-0000-4000-8000-000000000002","kind":"category","name":"Doações F4","direction":"income"}');
select public.finance_f1(current_setting('f4.org')::uuid,array[current_setting('f4.unit')::uuid],'catalog','{"id":"df400000-0000-4000-8000-000000000003","kind":"category","name":"Taxas F4","direction":"expense"}');
select lives_ok($$select public.finance_digital(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'purpose','{"id":"ef400000-0000-4000-8000-000000000001","version":0,"name":"Ofertas especiais","origin":"offering","account":"df400000-0000-4000-8000-000000000001","category":"df400000-0000-4000-8000-000000000002","feeCategory":"df400000-0000-4000-8000-000000000003","refundCategory":"df400000-0000-4000-8000-000000000003","creditCategory":"df400000-0000-4000-8000-000000000002","active":true}')$$,'finalidade válida criada');
select throws_ok($$select public.finance_digital(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'purpose','{"id":"ef400000-0000-4000-8000-000000000001","version":0,"name":"Ofertas especiais","origin":"offering","account":"df400000-0000-4000-8000-000000000001","category":"df400000-0000-4000-8000-000000000002","feeCategory":"df400000-0000-4000-8000-000000000003","refundCategory":"df400000-0000-4000-8000-000000000003","creditCategory":"df400000-0000-4000-8000-000000000002","active":true}')$$,'40001',null,'versão antiga não sobrescreve a finalidade');
reset role;
-- Only this isolated test fabricates a provider proof. Never run against production.
insert into private.finance_receivers(id,organization_id,unit_id,provider,environment,status,external_id,holder,holder_confirmed,beneficiary_units,account_id,created_by,expires_at) values('ff400000-0000-4000-8000-000000000001',current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'mercado_pago','production','configured','123','Titular fictício',true,array[current_setting('f4.unit')::uuid],'df400000-0000-4000-8000-000000000001','af400000-0000-4000-8000-000000000001',now()+interval '1 hour');
set local role authenticated;
select lives_ok($$select public.finance_digital(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'order','{"id":"af410000-0000-4000-8000-000000000001","purpose":"ef400000-0000-4000-8000-000000000001","receiver":"ff400000-0000-4000-8000-000000000001","gross":"10000","party":"Nome livre","sourceReference":"evento-1"}')$$,'pedido vinculado registrado sem cobrança');
select lives_ok($$select public.finance_digital(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'order','{"id":"af410000-0000-4000-8000-000000000001","purpose":"ef400000-0000-4000-8000-000000000001","receiver":"ff400000-0000-4000-8000-000000000001","gross":"10000","party":"Nome livre","sourceReference":"evento-1"}')$$,'pedido repetido não duplica');
select is(jsonb_array_length(public.finance_digital(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'list','{}')->'items'),1,'lista mostra pedido pendente sem prova');
reset role;
select is((select count(*)::integer from private.finance_digital_orders where organization_id=current_setting('f4.org')::uuid),1,'um pedido');
select is((select count(*)::integer from private.finance_entries where organization_id=current_setting('f4.org')::uuid),0,'pedido pendente não aumenta saldo');
select set_config('f4.proof',jsonb_build_object('reference','af410000-0000-4000-8000-000000000001','externalId','456','receiverExternalId','123','environment','production','currency','BRL','gross','10000','net','9650','refunded','0','fees',null,'state','approved','settlement','available','occurredAt',now()-interval '5 minutes','paidDate',current_date,'method','pix','installments',1)::text,true);
select lives_ok($$select private.finance_digital_ingest('ff400000-0000-4000-8000-000000000001',current_setting('f4.proof')::jsonb)$$,'prova sem taxa vai para revisão');
select is((select review_reason from private.finance_digital_receipts where external_id='456'),'fees_unknown','taxas não informadas não viram zero');
select is((select count(*)::integer from private.finance_entries where organization_id=current_setting('f4.org')::uuid),0,'taxa desconhecida não lança saldo presumido');
select set_config('f4.proof',(current_setting('f4.proof')::jsonb||jsonb_build_object('fees',jsonb_build_array(jsonb_build_object('kind','processing','amount','350')),'occurredAt',now()-interval '4 minutes'))::text,true);
select lives_ok($$select private.finance_digital_ingest('ff400000-0000-4000-8000-000000000001',current_setting('f4.proof')::jsonb)$$,'bruto e taxa lançados automaticamente');
select is((select count(*)::integer from private.finance_entries where organization_id=current_setting('f4.org')::uuid),2,'entrada e despesa de taxa separadas');
select is((select sum(case when kind='income' then amount_cents else -amount_cents end)::text from private.finance_entries where organization_id=current_setting('f4.org')::uuid),'9650','líquido 96,50 sem descontar taxa duas vezes');
select lives_ok($$select private.finance_digital_ingest('ff400000-0000-4000-8000-000000000001',current_setting('f4.proof')::jsonb)$$,'retorno repetido aceito sem duplicação');
select is((select count(*)::integer from private.finance_entries where organization_id=current_setting('f4.org')::uuid),2,'duplicidade não cria lançamento');
select throws_ok($$select private.finance_digital_ingest('ff400000-0000-4000-8000-000000000001',current_setting('f4.proof')::jsonb||'{"gross":"10001"}')$$,'22023',null,'valor divergente recusado');
select throws_ok($$select private.finance_digital_ingest('ff400000-0000-4000-8000-000000000001',current_setting('f4.proof')::jsonb||'{"environment":"sandbox"}')$$,'22023',null,'ambiente divergente recusado');
select set_config('f4.proof',(current_setting('f4.proof')::jsonb||jsonb_build_object('state','partially_refunded','refunded','2000','occurredAt',now()-interval '3 minutes'))::text,true);
select lives_ok($$select private.finance_digital_ingest('ff400000-0000-4000-8000-000000000001',current_setting('f4.proof')::jsonb)$$,'devolução parcial gera ajuste vinculado');
select is((select posted_refund::text from private.finance_digital_receipts where external_id='456'),'2000','devolução cumulativa de 20,00');
select is((select sum(case when kind='income' then amount_cents else -amount_cents end)::text from private.finance_entries where organization_id=current_setting('f4.org')::uuid),'7650','saldo ajustado sem apagar contribuição original');
select lives_ok($$select private.finance_digital_ingest('ff400000-0000-4000-8000-000000000001',current_setting('f4.proof')::jsonb||jsonb_build_object('state','pending','occurredAt',now()-interval '10 minutes'))$$,'evento atrasado ignorado');
select is((select snapshot->>'state' from private.finance_digital_receipts where external_id='456'),'partially_refunded','evento antigo não regride estado');
select lives_ok($$select private.finance_digital_ingest('ff400000-0000-4000-8000-000000000001',current_setting('f4.proof')::jsonb||jsonb_build_object('state','disputed','occurredAt',now()-interval '2 minutes'))$$,'contestação exige análise');
select is((select review_reason from private.finance_digital_receipts where external_id='456'),'dispute_requires_review','contestação não é devolução presumida');
select throws_ok($$update private.finance_entries set description='Adulteração' where organization_id=current_setting('f4.org')::uuid$$,'42501',null,'lançamento digital imutável exige ajuste vinculado');
select throws_ok($$delete from private.finance_digital_events$$,'42501',null,'histórico digital protegido');
select is((select sum(delta_cents)::text from public.church_ledger_lines where organization_id=current_setting('f4.org')::uuid),'0','partidas balanceadas');
select lives_ok($$select private.finance_digital_ingest('ff400000-0000-4000-8000-000000000001',current_setting('f4.proof')::jsonb||jsonb_build_object('state','refunded','refunded','10000','fees',jsonb_build_array(jsonb_build_object('kind','processing','amount','0')),'occurredAt',now()-interval '1 minute'))$$,'devolução total e crédito de taxa usam ajustes cumulativos');
select is((select sum(case when kind='income' then amount_cents else -amount_cents end)::text from private.finance_entries where organization_id=current_setting('f4.org')::uuid),'0','saldo final zero com contribuição original preservada');
select is((select posted_gross::text from private.finance_digital_receipts where external_id='456'),'10000','contribuição original continua 100,00');
select is((select count(*)::integer from private.finance_digital_links l join private.finance_digital_receipts r on r.id=l.receipt_id where r.external_id='456'),5,'todos os cinco lançamentos vinculados à mesma transação');
update private.finance_receivers set environment='sandbox' where id='ff400000-0000-4000-8000-000000000001';
set local role authenticated;
select lives_ok($$select public.finance_digital(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'order','{"id":"af410000-0000-4000-8000-000000000002","purpose":"ef400000-0000-4000-8000-000000000001","receiver":"ff400000-0000-4000-8000-000000000001","gross":"10000","party":"Teste sandbox","sourceReference":"teste-2"}')$$,'pedido de teste separado');
reset role;
select lives_ok($$select private.finance_digital_ingest('ff400000-0000-4000-8000-000000000001',current_setting('f4.proof')::jsonb||jsonb_build_object('reference','af410000-0000-4000-8000-000000000002','externalId','457','environment','sandbox','occurredAt',now()))$$,'sandbox aceita prova sem tocar no livro real');
select is((select posted_gross::text from private.finance_digital_receipts where external_id='457'),'0','sandbox não lança entrada');
select is((select review_reason from private.finance_digital_receipts where external_id='457'),'sandbox_no_ledger','sandbox claramente identificado');
update private.finance_receivers set environment='production' where id='ff400000-0000-4000-8000-000000000001';
set local role authenticated;
select lives_ok($$select public.finance_digital(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'order','{"id":"af410000-0000-4000-8000-000000000003","purpose":"ef400000-0000-4000-8000-000000000001","receiver":"ff400000-0000-4000-8000-000000000001","gross":"10000","party":"Teste fechado","sourceReference":"teste-3"}')$$,'pedido anterior ao fechamento');
reset role;
update public.church_ledger_periods set closed_through=current_date-1 where organization_id=current_setting('f4.org')::uuid;
select lives_ok($$select private.finance_digital_ingest('ff400000-0000-4000-8000-000000000001',current_setting('f4.proof')::jsonb||jsonb_build_object('reference','af410000-0000-4000-8000-000000000003','externalId','458','refunded','0','state','approved','paidDate',current_date-2,'occurredAt',now()))$$,'período fechado preserva prova na revisão');
select is((select review_reason from private.finance_digital_receipts where external_id='458'),'period_closed','fechamento não é contornado pelo processamento automático');
select is((select posted_gross::text from private.finance_digital_receipts where external_id='458'),'0','falha de fechamento não gera lançamento parcial');
update private.finance_receivers set status='revoked' where id='ff400000-0000-4000-8000-000000000001';
select throws_ok($$select private.finance_digital_ingest('ff400000-0000-4000-8000-000000000001',current_setting('f4.proof')::jsonb||jsonb_build_object('occurredAt',now()))$$,'42501',null,'revogação interrompe nova ingestão');
select * from finish();
rollback;
